/// Scratch probe (review-only, not for merge): does the delivered envelope
/// excerpt derive from the RAW body (redaction bypass) or the redacted text?
library;

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

const _secret = 'sk-live-canary-0123456789';

void main() {
  test('PROBE: envelope excerpt vs redaction', () {
    final manager = SubagentManager(parentSessionId: 'p', maxReplyChars: 200);
    manager.register(id: 'kid', name: 'kid', agentType: 'task', task: 't');
    final store = AgentOutputStore();
    final capture = DeliverableCapture(
      store: store,
      manager: manager,
      redact: (text) => text.replaceAll(_secret, '***REDACTED***'),
    );
    // Secret sits INSIDE the excerpt window (first ~cap chars).
    final body =
        'The API key is $_secret and here is the full report body. '
        '${'report ' * 40}';
    final record = capture.deliverReply('kid', body)!;
    final stored = store.get(record.outputId!)!;
    expect(stored, isNot(contains(_secret)),
        reason: 'stored artifact must be redacted');
    // The envelope the PARENT actually receives (subagent_tools.dart
    // passes the raw `message`).
    final envelope = capture.envelopeText(record, body);
    // ignore: avoid_print
    print('ENVELOPE>>>$envelope<<<');
    expect(
      envelope,
      isNot(contains(_secret)),
      reason: 'FAILS => envelope leaks the raw secret (redaction bypass)',
    );
  });
}

